+/**
+ * #2393 P1-4 -- "used by N projects", stated on every rule.
+ *
+ * This is the org half of the bidirectional link between the two DLP surfaces:
+ * the project's Data protection section says which rules it inherits FROM the
+ * library, and the library says which projects use each rule. Before this, the
+ * only place a project count appeared was inside the reach badge's detail
+ * sentence, and only for the `bound_to_project` reasons -- so a draft, disabled
+ * or detect-only rule, which is exactly what an admin is about to change,
+ * showed no indication that N projects were relying on it.
+ *
+ * `reach === undefined` means the backend did not send a delivery state. That
+ * renders as "not established", never as 0: an uncounted rule and a rule
+ * nobody uses are different facts, and only one of them is safe to delete.
+ */
+function ProjectUsageChip({ ruleId, reach }: { ruleId: string; reach?: DLPRuleReach }) {
+  const known = !!reach && reach.reason !== 'lookup_failed' && reach.reason !== 'not_computed' &&
+    reach.reason !== 'not_computed_too_many_rules';
+  const n = known ? reach!.project_bindings : undefined;
+  return (
+    <span
+      data-testid={`dlp-rule-project-usage-${ruleId}`}
+      data-project-count={typeof n === 'number' ? String(n) : 'unknown'}
+      className="text-xs text-[var(--cz-text-3)]"
+      title={
+        typeof n === 'number'
+          ? 'Projects this rule is directly attached to. Delivery through a policy version is counted separately by the delivery state below.'
+          : 'This rule was served without a delivery state, so its project usage was not established.'
+      }
+    >
+      {typeof n === 'number'
+        ? `Used by ${n} project${n === 1 ? '' : 's'}`
+        : 'Project usage not established'}
+    </span>
+  );
+}
