diff --git a/apps/control-zero-platform/backend/internal/api/handlers/bundle_dlp_projection_1999_test.go b/apps/control-zero-platform/backend/internal/api/handlers/bundle_dlp_projection_1999_test.go
new file mode 100644
index 000000000..90776cb8b
--- /dev/null
+++ b/apps/control-zero-platform/backend/internal/api/handlers/bundle_dlp_projection_1999_test.go
@@ -0,0 +1,254 @@
+package handlers
+
+// #1999: a bundle from a DLP-DISABLED org must never be byte-identical to one
+// from an ENABLED org that simply has no custom rules yet.
+//
+// Why this matters more than it reads: a live "DLP is not enforcing" report
+// took days to diagnose because nothing an SDK client could observe told those
+// two situations apart. `dlp_rules` is `omitempty`, so a nil slice removed the
+// key entirely, and an operator staring at the bundle could not distinguish:
+//
+//   - the org is not in the policy_dlp allow-list
+//   - the org's tier lacks the dlp_scanning entitlement
+//   - the global master switch is off
+//   - the org is fully enabled and genuinely has zero rules
+//
+// Only the last is healthy, and it is the one a reader assumes. Every wrong
+// theory survived contact with the evidence because the evidence was silent.
+//
+// These tests assert BOTH directions, per CLAUDE.md: an accidental coverage
+// change must fail as loudly as a regression.
+
+import (
+	"encoding/json"
+	"go/ast"
+	"go/parser"
+	"go/token"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+func decodeProjection(t *testing.T, raw []byte) map[string]any {
+	t.Helper()
+	var out map[string]any
+	if err := json.Unmarshal(raw, &out); err != nil {
+		t.Fatalf("bundle payload is not valid JSON: %v", err)
+	}
+	proj, ok := out["dlp_projection"]
+	if !ok {
+		t.Fatalf("dlp_projection is ABSENT from the bundle. It must be emitted " +
+			"unconditionally -- if it can be missing, then 'missing' means both " +
+			"'old bundle' and 'enabled with no rules', which is the exact " +
+			"ambiguity #1999 exists to remove.")
+	}
+	m, ok := proj.(map[string]any)
+	if !ok {
+		t.Fatalf("dlp_projection is %T, want an object", proj)
+	}
+	return m
+}
+
+// The core assertion. If this ever passes with equal bytes, the control is
+// back to being invisible.
+func TestDisabledBundleIsNotByteIdenticalToEnabledWithZeroRules(t *testing.T) {
+	payload := bundlePayload{
+		SchemaVersion: BundlePayloadSchemaVersion,
+		BundleID:      "b-1",
+		ProjectID:     "p-1",
+		Policies:      []bundlePolicy{},
+		// Deliberately nil: this is the shape BOTH situations produce.
+		DLPRules: nil,
+	}
+
+	disabled, err := marshalBundlePayload(payload, false)
+	if err != nil {
+		t.Fatalf("marshal disabled: %v", err)
+	}
+	enabled, err := marshalBundlePayload(payload, true)
+	if err != nil {
+		t.Fatalf("marshal enabled: %v", err)
+	}
+
+	if string(disabled) == string(enabled) {
+		t.Fatalf("a DLP-DISABLED bundle is byte-identical to an ENABLED bundle "+
+			"with zero rules. An SDK client cannot tell 'the security control "+
+			"is off' from 'nothing to scan for', and will read the reassuring "+
+			"one. payload=%s", string(disabled))
+	}
+
+	if got := decodeProjection(t, disabled)["enabled"]; got != false {
+		t.Errorf("disabled bundle reports dlp_projection.enabled = %v, want false", got)
+	}
+	if got := decodeProjection(t, enabled)["enabled"]; got != true {
+		t.Errorf("enabled bundle reports dlp_projection.enabled = %v, want true", got)
+	}
+}
+
+// The opposite direction: a disabled projection must never advertise rules,
+// even if a caller somehow left some on the payload. Silence about a control
+// being off is the defect; over-reporting it is a different lie.
+func TestDisabledProjectionNeverAdvertisesRules(t *testing.T) {
+	payload := bundlePayload{
+		SchemaVersion: BundlePayloadSchemaVersion,
+		DLPRules: []bundleDLPRule{
+			{ID: "r-1", Name: "aws key", Pattern: "AKIA[A-Z0-9]{16}", Action: "block"},
+		},
+	}
+
+	raw, err := marshalBundlePayload(payload, true)
+	if err != nil {
+		t.Fatalf("marshal: %v", err)
+	}
+	proj := decodeProjection(t, raw)
+	if got := proj["rule_count"]; got != float64(1) {
+		t.Errorf("rule_count = %v, want 1 -- the count must match what was actually carried", got)
+	}
+}
+
+// rule_count is redundant with len(dlp_rules) ON PURPOSE: it is the producer
+// asserting its intent, so a consumer can catch a mismatch instead of reading
+// an empty array as "nothing configured".
+func TestRuleCountMatchesTheRulesActuallyCarried(t *testing.T) {
+	for _, n := range []int{0, 1, 5} {
+		rules := make([]bundleDLPRule, 0, n)
+		for i := 0; i < n; i++ {
+			rules = append(rules, bundleDLPRule{ID: string(rune('a' + i))})
+		}
+		raw, err := marshalBundlePayload(bundlePayload{DLPRules: rules}, true)
+		if err != nil {
+			t.Fatalf("marshal n=%d: %v", n, err)
+		}
+		if got := decodeProjection(t, raw)["rule_count"]; got != float64(n) {
+			t.Errorf("n=%d: rule_count = %v, want %d", n, got, n)
+		}
+	}
+}
+
+// The chokepoint guard.
+//
+// A test that new code can walk around is not a chokepoint (CLAUDE.md). The
+// dlp_rules field had SIX assignment sites across THREE serving paths; if the
+// projection status were stamped beside each one, the first new path would
+// silently emit an ambiguous bundle again -- which is precisely how #1927 and
+// #1931 happened.
+//
+// So this asserts structurally: within this package, a bundlePayload becomes
+// bytes ONLY inside marshalBundlePayload.
+func TestBundlePayloadIsOnlyMarshalledThroughTheChokepoint(t *testing.T) {
+	fset := token.NewFileSet()
+	entries, err := os.ReadDir(".")
+	if err != nil {
+		t.Fatalf("read package dir: %v", err)
+	}
+
+	var offenders []string
+	scanned := 0
+
+	for _, e := range entries {
+		name := e.Name()
+		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
+			continue
+		}
+		src, err := os.ReadFile(name)
+		if err != nil {
+			t.Fatalf("read %s: %v", name, err)
+		}
+		file, err := parser.ParseFile(fset, name, src, 0)
+		if err != nil {
+			t.Fatalf("parse %s: %v", name, err)
+		}
+		scanned++
+
+		for _, decl := range file.Decls {
+			fn, ok := decl.(*ast.FuncDecl)
+			if !ok || fn.Name.Name == "marshalBundlePayload" {
+				continue
+			}
+
+			// Resolve which locals in THIS function are actually bundlePayload.
+			//
+			// Matching on the identifier name alone was wrong and the first run
+			// proved it: it flagged encodeCredentialBundle (credential_bundle_
+			// handler.go) and FirstCallStatus (stubs.go), both of which marshal
+			// a variable that happens to be spelled `payload` but is a DIFFERENT
+			// type. A guard that cries wolf is the failure in the other
+			// direction -- it is what teaches people to delete the guard, and
+			// then the real regression walks through.
+			bundleVars := map[string]bool{}
+			ast.Inspect(fn, func(n ast.Node) bool {
+				switch d := n.(type) {
+				case *ast.AssignStmt: // payload := bundlePayload{...}
+					for i, rhs := range d.Rhs {
+						cl, ok := rhs.(*ast.CompositeLit)
+						if !ok || i >= len(d.Lhs) {
+							continue
+						}
+						if id, ok := cl.Type.(*ast.Ident); ok && id.Name == "bundlePayload" {
+							if lhs, ok := d.Lhs[i].(*ast.Ident); ok {
+								bundleVars[lhs.Name] = true
+							}
+						}
+					}
+				case *ast.DeclStmt: // var payload bundlePayload
+					gd, ok := d.Decl.(*ast.GenDecl)
+					if !ok {
+						return true
+					}
+					for _, s := range gd.Specs {
+						vs, ok := s.(*ast.ValueSpec)
+						if !ok {
+							continue
+						}
+						if id, ok := vs.Type.(*ast.Ident); ok && id.Name == "bundlePayload" {
+							for _, nm := range vs.Names {
+								bundleVars[nm.Name] = true
+							}
+						}
+					}
+				}
+				return true
+			})
+			if len(bundleVars) == 0 {
+				continue
+			}
+
+			ast.Inspect(fn, func(n ast.Node) bool {
+				call, ok := n.(*ast.CallExpr)
+				if !ok {
+					return true
+				}
+				sel, ok := call.Fun.(*ast.SelectorExpr)
+				if !ok || sel.Sel.Name != "Marshal" {
+					return true
+				}
+				pkg, ok := sel.X.(*ast.Ident)
+				if !ok || pkg.Name != "json" || len(call.Args) != 1 {
+					return true
+				}
+				arg, ok := call.Args[0].(*ast.Ident)
+				if !ok || !bundleVars[arg.Name] {
+					return true
+				}
+				offenders = append(offenders, filepath.Join(name,
+					fset.Position(call.Pos()).String())+" in "+fn.Name.Name)
+				return true
+			})
+		}
+	}
+
+	// Positive control: if the walk scanned nothing, a clean result would be
+	// meaningless. "Not run" must never read as "ran and found nothing".
+	if scanned == 0 {
+		t.Fatal("scanned 0 Go files -- the guard did not actually run, so its " +
+			"clean result proves nothing")
+	}
+
+	if len(offenders) > 0 {
+		t.Fatalf("bundlePayload is marshalled outside marshalBundlePayload at %v.\n"+
+			"That path emits a bundle with no dlp_projection status, so a "+
+			"missing dlp_rules key becomes ambiguous again (#1999). Route it "+
+			"through marshalBundlePayload(payload, dlpEnabled).", offenders)
+	}
+}

diff --git a/sdks/node/controlzero/tests/kiroAdapterClientPin.test.ts b/sdks/node/controlzero/tests/kiroAdapterClientPin.test.ts
new file mode 100644
index 000000000..5e599c36d
--- /dev/null
+++ b/sdks/node/controlzero/tests/kiroAdapterClientPin.test.ts
@@ -0,0 +1,132 @@
+// The Kiro IDE shim must PIN CONTROLZERO_CLIENT, not merely DEFAULT it.
+// Cross-SDK parity with the Python
+// sdks/python/controlzero/tests/test_kiro_adapter.py section of the same name.
+//
+// Kiro spawns this hook with the IDE's environment inherited, so a
+// CONTROLZERO_CLIENT the user exported in their shell (or that another agent's
+// launcher set) reaches the shim. `defaultRunner` pinned CZ_KIRO_SURFACE
+// unconditionally but guarded CONTROLZERO_CLIENT with `=== undefined`, so that
+// foreign value SURVIVED into the hook-check child. Adapter selection honours
+// an explicit pin above every other signal -- deliberately, it is the
+// operator's override -- so those IDE tool calls were claimed by ANOTHER host's
+// adapter.
+//
+// Enforcement still worked: every adapter decides by exit code, so a deny still
+// blocked. ATTRIBUTION and KEY SELECTION are what broke -- hook-check resolves
+// the per-agent API key from the SELECTED adapter's canonical source, so a
+// wrong adapter reads a DIFFERENT integration's config. The events spool,
+// upload and ingest cleanly into another project under that project's DLP
+// profile while the installed project's dashboard shows nothing. Nothing
+// anomalous is visible anywhere: the #1011 silent wrong-tenant class.
+//
+// WHY THIS FILE MOCKS `node:child_process` RATHER THAN INJECTING A RUNNER:
+// `runKiroAdapter`'s third parameter replaces `defaultRunner` wholesale, and
+// `defaultRunner` is where the env is built. A capturing runner (the pattern in
+// kiroAdapter.test.ts) therefore sees the RAW env and can never observe this
+// bug. Mocking spawnSync exercises the real `defaultRunner` and reads the env
+// actually handed to the child.
+
+import { describe, it, expect, beforeEach, vi } from 'vitest';
+
+const { spawnSyncMock } = vi.hoisted(() => ({ spawnSyncMock: vi.fn() }));
+
+vi.mock('node:child_process', () => ({ spawnSync: spawnSyncMock }));
+
+import { runKiroAdapter } from '../src/cli/kiroAdapter.js';
+
+/** Values a Kiro IDE hook can plausibly inherit: another agent's launcher, a
+ * CI pin, or a developer who exported one in their shell and forgot. */
+const FOREIGN_CLIENTS = ['claude-code', 'kiro-cli', 'codex', 'antigravity_ide'];
+
+const TOOL_PAYLOAD = JSON.stringify({
+  toolName: 'execute_bash',
+  toolArgs: { command: 'rm -rf /' },
+});
+
+/** The env object `defaultRunner` handed to spawnSync on its only call. */
+function childEnvFromTheOnlySpawn(): NodeJS.ProcessEnv {
+  expect(
+    spawnSyncMock.mock.calls.length,
+    'the hook-check engine was never spawned -- this assertion would otherwise ' +
+      'pass vacuously on a shim that silently skipped the child'
+  ).toBe(1);
+  const options = spawnSyncMock.mock.calls[0][2] as { env: NodeJS.ProcessEnv };
+  return options.env;
+}
+
+describe('Kiro IDE shim pins CONTROLZERO_CLIENT', () => {
+  beforeEach(() => {
+    spawnSyncMock.mockReset();
+    spawnSyncMock.mockReturnValue({ status: 0 });
+  });
+
+  it.each(FOREIGN_CLIENTS)(
+    'an inherited CONTROLZERO_CLIENT=%s does not survive into the hook-check child',
+    (inherited) => {
+      runKiroAdapter(['kiro-adapter', 'preToolUse'], {
+        USER_PROMPT: TOOL_PAYLOAD,
+        CONTROLZERO_CLIENT: inherited,
+      });
+
+      const childEnv = childEnvFromTheOnlySpawn();
+      expect(
+        childEnv.CONTROLZERO_CLIENT,
+        `an inherited CONTROLZERO_CLIENT=${inherited} survived into the ` +
+          'hook-check child; the IDE call is attributed to that host and ' +
+          'resolves ITS per-integration API key -- events land in another ' +
+          "project under that project's DLP profile (#1011 wrong-tenant class)"
+      ).toBe('kiro-ide');
+      // The surface marker was always pinned. Assert both so a future edit
+      // cannot regress one without the other noticing.
+      expect(childEnv.CZ_KIRO_SURFACE).toBe('ide');
+    }
+  );
+
+  it('pins the client when nothing was inherited (the pre-existing behaviour)', () => {
+    runKiroAdapter(['kiro-adapter', 'preToolUse'], { USER_PROMPT: TOOL_PAYLOAD });
+
+    const childEnv = childEnvFromTheOnlySpawn();
+    expect(childEnv.CONTROLZERO_CLIENT).toBe('kiro-ide');
+    expect(childEnv.CZ_KIRO_SURFACE).toBe('ide');
+  });
+
+  const eventCases: Array<[string, string]> = [];
+  for (const event of ['preToolUse', 'userPromptSubmit', 'fileEdited', 'fileCreated']) {
+    for (const inherited of FOREIGN_CLIENTS) eventCases.push([event, inherited]);
+  }
+
+  it.each(eventCases)(
+    'event %s pins the client over an inherited %s',
+    (event, inherited) => {
+      // The pin is not conditional on the event kind: the deciding gates and
+      // the observe-only file events all attribute to the Kiro IDE surface.
+      runKiroAdapter(['kiro-adapter', event], {
+        USER_PROMPT: event === 'preToolUse' ? TOOL_PAYLOAD : '/tmp/x',
+        CONTROLZERO_CLIENT: inherited,
+      });
+
+      expect(
+        childEnvFromTheOnlySpawn().CONTROLZERO_CLIENT,
+        `event ${event} leaked an inherited CONTROLZERO_CLIENT=${inherited} ` +
+          'into the hook-check child'
+      ).toBe('kiro-ide');
+    }
+  );
+
+  it('leaves the rest of the inherited environment untouched', () => {
+    // The shim overwrites exactly two keys. Pinning the client must not turn
+    // into sanitising the environment -- the child needs HOME, PATH, the
+    // operator's CONTROLZERO_API_URL and so on.
+    runKiroAdapter(['kiro-adapter', 'preToolUse'], {
+      USER_PROMPT: TOOL_PAYLOAD,
+      CONTROLZERO_CLIENT: 'claude-code',
+      CONTROLZERO_API_URL: 'https://api.example.invalid',
+      PATH: '/usr/bin',
+    });
+
+    const childEnv = childEnvFromTheOnlySpawn();
+    expect(childEnv.CONTROLZERO_API_URL).toBe('https://api.example.invalid');
+    expect(childEnv.PATH).toBe('/usr/bin');
+    expect(childEnv.USER_PROMPT).toBe(TOOL_PAYLOAD);
+  });
+});

